/** "How Towinly began", parts 1 to 6, in order. */
export const ORIGIN_RUN = ["37", "38", "39", "42", "40", "41"].map(art);

/** The row at the end of the Story tab, each linking to the Instagram account. */
export const ONLINE_ROW = ["02", "37", "38", "39", "42", "40", "41", "47"].map(art);
